    s = []
    h = n // 100
    r = n % 100
    if h:
        s.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        s.append(TENS[r // 10])
    if r % 10:
        s.append(ONES[r % 10])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
