    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q = n // val
        n = n % val
        if q:
            if name == 'bin' and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
