            msg = 'Kartınızın son dört hanesini söyler misiniz?'
    else:
        tries += 1
        vars['cand_json'] = '[]'
        alln = []
        for c in el:
            if cname(c) and cname(c) not in alln:
                alln.append(cname(c))
        msg = 'Bu bilgiyle eşleşen bir kartınız bulunmuyor. Kartlarınız: ' + joinlist(alln, ' ve ') + '. Hangisinin borcunu öğrenmek istersiniz?'
