import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
def w3(n):
    s = []
    h = n // 100
    r = n % 100
    if h:
        s.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        s.append(TENS[r // 10])
    if r % 10:
        s.append(ONES[r % 10])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q = n // val
        n = n % val
        if q:
            if name == 'bin' and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
CUR = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('Dolar', 'Dolar', 'sent'), EUR=('Euro', 'Euro', 'sent'), GBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))
def fnum(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def money(x, cur):
    c = int(round(abs(fnum(x)) * 100))
    whole = c // 100
    frac = c % 100
    full, unit, sub = CUR[cur]
    if frac == 0:
        return words(whole) + ' ' + full
    if whole == 0:
        return words(frac) + ' ' + sub
    return words(whole) + ' ' + unit + ' ' + words(frac) + ' ' + sub
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if d is None:
        return str(s or '')
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def suffix(s):
    d = pdate(s)
    if d is None:
        return ''
    w = words(d.year).split(' ')[-1]
    v = [ch for ch in w if ch in 'aıoueiöü']
    lv = v[-1] if v else 'a'
    hv = dict(a='ı', ı='ı', o='u', u='u', e='i', i='i', ö='ü', ü='ü')[lv]
    c = 't' if w[-1] in 'çfhkpsşt' else 'd'
